from rest_framework import viewsets, permissions
from rest_framework.exceptions import PermissionDenied
from rest_framework.decorators import action
from rest_framework.response import Response
from .models import TeamDashboard
from .serializers import DashboardSerializer

class TeamDashboardViewSet(viewsets.ModelViewSet):
    serializer_class = DashboardSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return TeamDashboard.objects.filter(workspace__members=self.request.user)

    @action(detail=True, methods=["post"])
    def transfer_workspace(self, request, pk=None):
        dashboard = self.get_object()
        dest_workspace_id = request.data.get("dest_workspace_id")
        if not request.user.workspaces.filter(id=dest_workspace_id).exists():
            raise PermissionDenied("You are not a member of the destination workspace")
        dashboard.workspace_id = dest_workspace_id
        dashboard.save()
        return Response({"status": "transferred", "new_workspace_id": dest_workspace_id})
